17	// feed is a blocking byte queue used as the underlying reader in
18	// unidirectional tests: Read blocks while it is empty and open.
19	type feed struct {
20		mu     sync.Mutex
21		cond   *sync.Cond
22		data   []byte
23		closed bool
24	}
25	
26	// closedReader is a read end that is already at EOF, for send-only
27	// sessions whose inbound direction is never used.
28	type closedReader struct{}
29	
30	func (closedReader) Read([]byte) (int, error) { return 0, io.EOF }
31	
32	func newFeed() *feed {
33		f := &feed{}
34		f.cond = sync.NewCond(&f.mu)
35		return f
36	}
37	
38	func (f *feed) replace(p []byte) {
39		f.mu.Lock()
40		f.data = append(f.data[:0], p...)
41		f.cond.Broadcast()
42		f.mu.Unlock()
43	}
44	
45	func (f *feed) closeFeed() {
46		f.mu.Lock()
47		f.closed = true
48		f.cond.Broadcast()
49		f.mu.Unlock()
50	}
51	
52	func (f *feed) Read(p []byte) (int, error) {
53		f.mu.Lock()
54		for len(f.data) == 0 && !f.closed {
55			f.cond.Wait()
56		}
57		if len(f.data) > 0 {
58			n := copy(p, f.data)
59			f.data = f.data[n:]
60			f.mu.Unlock()
61			return n, nil
62		}
63		f.mu.Unlock()
64		return 0, io.EOF
65	}
