67	// newSender builds a reliable writer whose flushed bytes land in buf.
68	// Its read side goes to io.Discard because these tests drive acks
69	// deterministically.
70	func newSender(t *testing.T, buf *bytes.Buffer, window int, dir string) *ReliableSession {
71		t.Helper()
72		rs, err := NewReliable(NewSession(buf, closedReader{}), ReliableConfig{Window: window, StateDir: dir})
73		if err != nil {
74			t.Fatalf("NewReliable sender: %v", err)
75		}
76		t.Cleanup(func() { rs.Close() })
77		return rs
78	}
