80	// newReceiver builds a reliable reader over f. Standalone acks from its
81	// pump go to io.Discard.
82	func newReceiver(t *testing.T, f *feed, window int, dir string) *ReliableSession {
83		t.Helper()
84		rs, err := NewReliable(NewSession(io.Discard, f), ReliableConfig{Window: window, StateDir: dir})
85		if err != nil {
86			t.Fatalf("NewReliable receiver: %v", err)
87		}
88		t.Cleanup(func() { rs.Close() })
89		return rs
90	}
91	
92	// envWire serializes reliable envelopes into a concatenated outer wire.
93	func envWire(t *testing.T, es ...envelope) []byte {
94		t.Helper()
95		var buf bytes.Buffer
96		s := NewSession(&buf, nil)
97		for _, e := range es {
98			b, err := encodeEnvelope(e)
99			if err != nil {
100				t.Fatalf("encodeEnvelope: %v", err)
101			}
102			if err := s.WriteFrame(Frame{Kind: outerKind, Payload: b}); err != nil {
103				t.Fatalf("WriteFrame: %v", err)
104			}
105		}
106		if err := s.Flush(); err != nil {
107			t.Fatalf("Flush: %v", err)
108		}
109		return buf.Bytes()
110	}
111	
112	func dataEnv(seq uint32, ack uint32, f ReliableFrame) envelope {
113		return envelope{seq: seq, ack: ack, typ: envTypeData, flags: f.Flags, kind: f.Kind, payload: f.Payload}
114	}
115	
116	func drainReliable(t *testing.T, rs *ReliableSession, want int) []ReliableFrame {
117		t.Helper()
118		got := make([]ReliableFrame, 0, want)
119		for i := 0; i < want; i++ {
