121			if err != nil {
122				t.Fatalf("ReadFrame %d: %v", i, err)
123			}
124			got = append(got, f)
125		}
126		return got
127	}
128	
129	func assertFrames(t *testing.T, got []ReliableFrame, want []ReliableFrame) {
130		t.Helper()
131		if len(got) != len(want) {
132			t.Fatalf("got %d frames, want %d", len(got), len(want))
133		}
134		for i := range want {
135			if got[i].Flags != want[i].Flags || got[i].Kind != want[i].Kind ||
136				!bytes.Equal(got[i].Payload, want[i].Payload) {
137				t.Fatalf("frame %d = {flags=%d kind=%d payload=%q}, want {flags=%d kind=%d payload=%q}",
138					i, got[i].Flags, got[i].Kind, got[i].Payload,
139					want[i].Flags, want[i].Kind, want[i].Payload)
140			}
141		}
142	}
