144	// parseWireEnvelopes decodes flushed sender bytes back into envelopes.
145	func parseWireEnvelopes(t *testing.T, wire []byte) []envelope {
146		t.Helper()
147		s := NewSession(nil, bytes.NewReader(wire))
148		var out []envelope
149		for {
150			fr, err := s.ReadFrame()
151			if errors.Is(err, io.EOF) {
152				return out
153			}
154			if err != nil {
155				t.Fatalf("outer ReadFrame: %v", err)
156			}
157			e, err := decodeEnvelope(fr.Payload)
158			if err != nil {
159				t.Fatalf("decodeEnvelope: %v", err)
160			}
161			out = append(out, e)
162		}
163	}
