175	// ---- requirement tests -----------------------------------------------------
176	
177	func TestReliableOrderingFlagsKindPayload(t *testing.T) {
178		dir := t.TempDir()
179		var wire bytes.Buffer
180		snd := newSender(t, &wire, 8, dir)
181	
182		in := []ReliableFrame{
183			{Flags: 0x0001, Kind: 7, Payload: []byte("first")},
184			{Flags: 0xBEEF, Kind: 200, Payload: nil}, // empty payload
185			{Flags: 0, Kind: 0, Payload: []byte{}},   // explicit empty
186			{Flags: 0x0002, Kind: 254, Payload: []byte("fourth")},
187		}
188		for _, f := range in {
189			if err := snd.WriteFrame(f); err != nil {
190				t.Fatalf("WriteFrame: %v", err)
191			}
