513	func TestReliableRestartResumesAfterLastAcked(t *testing.T) {
514		dir := t.TempDir()
515		cfg := ReliableConfig{Window: 4, StateDir: dir}
516	
517		// Phase 1: four frames are written and flushed. The receiver gets
518		// frames 0 and 1 before the "connection" drops.
519		var wire1 bytes.Buffer
520		s1, err := NewReliable(NewSession(&wire1, closedReader{}), cfg)
521		if err != nil {
522			t.Fatalf("NewReliable: %v", err)
523		}
524		for i := 0; i < 4; i++ {
525			if err := s1.WriteFrame(ReliableFrame{Kind: uint8(i + 1), Payload: []byte(fmt.Sprintf("frame%d", i))}); err != nil {
526				t.Fatalf("WriteFrame %d: %v", i, err)
527			}
528		}
529		if err := s1.Flush(); err != nil {
530			t.Fatalf("Flush: %v", err)
531		}
532	
533		f := newFeed()
534		rcv := newReceiver(t, f, cfg.Window, t.TempDir())
535		f.replace(wire1.Bytes())
536		first := drainReliable(t, rcv, 2)
537		if string(first[0].Payload) != "frame0" || string(first[1].Payload) != "frame1" {
538			t.Fatalf("phase 1 frames = %+v", first)
539		}
540	
541		// Cumulative ack (next expected = 2) reaches the sender: the window
542		// slides and the position is checkpointed.
543		s1.applyAck(2)
544		if err := s1.Close(); err != nil {
545			t.Fatalf("close: %v", err)
546		}
547	
548		// Phase 2: the sender restarts with the same state dir on a new
549		// connection. It resumes strictly after the last acked position:
550		// seq 2 and 3 go out, 0 and 1 are never re-sent.
551		var wire2 bytes.Buffer
552		s2, err := NewReliable(NewSession(&wire2, closedReader{}), cfg)
553		if err != nil {
554			t.Fatalf("restart NewReliable: %v", err)
555		}
556		if s2.sendBase != 2 || s2.sendNext != 4 {
557			t.Fatalf("restart positions = base %d next %d, want 2/4", s2.sendBase, s2.sendNext)
558		}
559		if err := s2.Flush(); err != nil {
560			t.Fatalf("restart Flush: %v", err)
561		}
