936	// TestReliableConcurrentReadersExactlyOnce mirrors the lower-layer
937	// guarantee: with several goroutines sharing one receiver, every frame
938	// is handed out exactly once and in sequence.
939	func TestReliableConcurrentReadersExactlyOnce(t *testing.T) {
940		const n = 400
941		frames := make([]ReliableFrame, n)
942		for i := range frames {
943			frames[i] = ReliableFrame{Kind: uint8(i), Payload: []byte(fmt.Sprintf("%08d", i))}
944		}
945		envs := make([]envelope, n)
946		for i := range frames {
947			envs[i] = dataEnv(uint32(i), 0, frames[i])
948		}
949		wire := envWire(t, envs...)
950	
951		f := newFeed()
952		rcv := newReceiver(t, f, n, t.TempDir())
953		f.replace(wire)
954	
955		const readers = 8
956		var mu sync.Mutex
957		got := make([]ReliableFrame, 0, n)
958		var wg sync.WaitGroup
959		for r := 0; r < readers; r++ {
960			wg.Add(1)
961			go func() {
962				defer wg.Done()
963				for {
964					fr, err := rcv.ReadFrame()
965					if err != nil {
966						return
967					}
968					mu.Lock()
969					if len(got) < n {
970						got = append(got, fr)
971					}
972					mu.Unlock()
973				}
974			}()
975		}
976		// Wait until n frames are out, then close the feed so readers drain
977		// at EOF.
978		for {
979			mu.Lock()
980			done := len(got) == n
981			mu.Unlock()
982			if done {
983				break
984			}
985		}
986		f.closeFeed()
987		wg.Wait()
988	
989		mu.Lock()
990		defer mu.Unlock()
991		if len(got) != n {
992			t.Fatalf("delivered %d frames, want %d", len(got), n)
993		}
994		// Concurrent delivery order is arbitrary, but the SET of delivered
995		// frames must be exactly the input: no loss, no duplication.
996		seen := make(map[string]int, n)
997		for _, fr := range got {
998			seen[string(fr.Payload)]++
999		}
1000		for i := 0; i < n; i++ {
1001			key := fmt.Sprintf("%08d", i)
1002			if seen[key] != 1 {
1003				t.Fatalf("frame %q delivered %d times, want exactly 1", key, seen[key])
1004			}
1005		}
