package codec

import (
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"os"
	"path/filepath"
	"sync"
)

// Channel multiplexing on top of one ReliableSession.
//
// A Mux carries several independent logical channels over a single
// reliable session. Every multiplexed message is the payload of one
// reliable data frame, prefixed by this layer's own mux header; the
// reliable wire format, the codec frame format and every established
// entry, constant and error value below this layer keep their exact
// byte-level semantics.
//
// Mux header layout inside a reliable payload (all multi-byte fields
// big-endian):
//
//	+----------+---------+--------+---------+=========+
//	| chan (2) | seq (4) | fl(1)  | crc32(4)| payload |
//	+----------+---------+--------+---------+=========+
//
//   - chan: the channel number the frame belongs to.
//   - seq: per-channel write sequence, numbered in write order.
//   - fl: bit 0 marks the closing FIN frame; bit 1 marks a standalone
//     channel acknowledgement.
//   - crc32: IEEE CRC of the other 7 header bytes plus the payload.
//
// The FIN and ack flags are never combined: a FIN frame is delivered
// data that also closes its channel; an ack carries no payload.
//
// Delivery guarantees:
//   - Frames within one channel are delivered in write order exactly
//     once; channels are independent, so a gap on one channel never
//     blocks delivery on another.
//   - The send side hands transmission opportunities out round-robin
//     across channels, so one busy channel can never starve the others.
//   - Every channel has its own in-flight quota; a write that finds the
//     quota full returns the established over-limit value ErrWindowFull
//     and an oversized payload returns ErrTooLarge. A rejected frame is
//     neither queued nor journaled and consumes no sequence, so it takes
//     no quota.
//   - A channel opens on its first write and its write side can be
//     closed independently; once the peer has received the channel's
//     remaining frames its next read on that channel returns io.EOF.
//     Writing to, or closing, an already closed channel returns
//     ErrChannelClosed.
//
// As on the reliable layer, nothing is transmitted before Flush; Flush
// is also the retransmit operation after a restart.
const (
	// MuxHeaderSize is this layer's per-frame overhead:
	// 2 (chan) + 4 (seq) + 1 (flags) + 4 (crc32).
	MuxHeaderSize = 2 + 4 + 1 + 4

	// MuxMaxPayload is the largest payload a multiplexed frame may
	// carry; MuxHeaderSize bytes are reserved inside the reliable
	// payload, whose own limit stays ReliableMaxPayload.
	MuxMaxPayload = ReliableMaxPayload - MuxHeaderSize

	// mux header field offsets.
	mhChanOff  = 0
	mhSeqOff   = 2
	mhFlagOff  = 6
	mhCRCOff   = 7
	mhBodyOff  = 11
	mhFlagData = 0
	mhFlagFin  = 1 << 0
	mhFlagAck  = 1 << 1
)

// ErrChannelClosed is returned by a write or close on a channel whose
// write side has already been closed.
var ErrChannelClosed = errors.New("codec: channel closed")

// MuxConfig configures a Mux.
type MuxConfig struct {
	// Channels is the number of logical channels the session carries,
	// numbered 0..Channels-1. It must be positive.
	Channels int

	// Window is the per-channel in-flight quota in frames, enforced
	// independently for every channel. It must be positive.
	Window int

	// StateDir holds the checkpoint files and replay journal used to
	// resume the write side after a restart. It is created if missing.
	StateDir string
}

// ChannelFrame is one caller-visible multiplexed frame.
type ChannelFrame struct {
	Channel uint16
	Flags   uint16
	Kind    uint8
	Payload []byte
}

// queuedFrame is one accepted frame waiting for a transmission
// opportunity or an acknowledgement.
type queuedFrame struct {
	channel uint16
	seq     uint32
	flags   uint16
	kind    uint8
	payload []byte
	fin     bool
}

// muxChannel is one send-side channel.
type muxChannel struct {
	next   uint32 // next sequence a write gets
	open   bool   // opened by a first write
	closed bool   // write side closed (a FIN may still be queued)
}

// Mux is a multiplexing layer wrapping one ReliableSession. Create it
// with NewMux; the wrapped session must not be used directly while the
// Mux owns it.
type Mux struct {
	rel *ReliableSession
	cfg MuxConfig

	mu sync.Mutex
	// queue holds every accepted but unacknowledged frame, in the exact
	// arrival order across all channels; each channel's frames appear in
	// seq order inside it. Its length is bounded by Channels*Window.
	queue []*queuedFrame
	chans []muxChannel
	// rr is the round-robin cursor: the channel at which the next Flush
	// starts handing out opportunities.
	rr    int
	finsi map[muxSeq]bool
	log   *muxLog

	rmu sync.Mutex
	// bases is the per-channel next-due sequence. It is read by the ack
	// send path without rmu, mirroring the reliable layer's split.
	bases []uint32
	// held parks in-window out-of-order frames keyed by channel+seq.
	held map[muxSeq]ChannelFrame
	// finDelivered marks a channel whose FIN reached the reader; the
	// channel then reports io.EOF stickily.
	finDelivered []bool
	rerr         error

	// standCh serializes standalone ack sends so a data Flush and ack
	// frames never interleave on the wire.
	standCh chan standAck
	stopCh  chan struct{}
	doneCh  chan struct{}
}

// muxSeq identifies a frame within one channel.
type muxSeq struct {
	ch  uint16
	seq uint32
}

// standAck is one standalone channel acknowledgement handed to the
// background ack sender.
type standAck struct {
	ch   uint16
	next uint32
}

// NewMux wraps rel in a multiplexing session. Write state in
// cfg.StateDir is consulted when present: a fresh directory starts every
// channel at sequence 0 with every channel open, while a directory left
// by a crashed or restarted process resumes from the earliest confirmed
// per-channel positions held by its checkpoints and journal.
func NewMux(rel *ReliableSession, cfg MuxConfig) (*Mux, error) {
	if cfg.Channels <= 0 {
		return nil, errors.New("codec: mux channel count must be positive")
	}
	if cfg.Window <= 0 {
		return nil, errors.New("codec: mux window must be positive")
	}
	if cfg.StateDir == "" {
		return nil, errors.New("codec: mux session requires a state directory")
	}
	if err := os.MkdirAll(cfg.StateDir, 0o755); err != nil {
		return nil, err
	}

	m := &Mux{
		rel:          rel,
		cfg:          cfg,
		chans:        make([]muxChannel, cfg.Channels),
		finsi:        make(map[muxSeq]bool),
		bases:        make([]uint32, cfg.Channels),
		held:         make(map[muxSeq]ChannelFrame),
		finDelivered: make([]bool, cfg.Channels),
		standCh:      make(chan standAck, cfg.Channels),
		stopCh:       make(chan struct{}),
		doneCh:       make(chan struct{}),
	}

	// Resume the per-channel acknowledged positions before opening the
	// journal: reconciliation takes the EARLIER position held by either
	// file, so an unacknowledged frame is never skipped and an
	// acknowledged one never renumbered onto a used sequence.
	for ch := 0; ch < cfg.Channels; ch++ {
		ack, err := loadMuxCheckpoint(cfg.StateDir, uint16(ch))
		if err != nil {
			return nil, err
		}
		m.bases[ch] = ack
	}

	var err error
	m.log, err = openMuxLog(cfg.StateDir)
	if err != nil {
		return nil, err
	}

	for _, rec := range m.log.recs {
		ch := int(rec.ch)
		if ch >= cfg.Channels {
			return nil, fmt.Errorf("codec: mux journal carries channel %d beyond %d: %w",
				ch, cfg.Channels-1, ErrChecksum)
		}
		c := &m.chans[ch]
		c.open = true
		if rec.fin {
			// A FIN is the last thing a channel ever sends: the write
			// side stays closed after recovery and no later record can
			// exist for the channel.
			c.closed = true
		}
		frame := rec.frame()
		m.queue = append(m.queue, &frame)
		if rec.seq >= c.next {
			c.next = rec.seq + 1
		}
	}
	// Queue order must stay the arrival order after a restart too. The
	// journal is written in arrival order, but sort defensively so
	// round-robin Flush and replay agree regardless.
	sortQueue(m.queue)

	go m.pumpAck()
	return m, nil
}

// WriteFrame enqueues f on channel f.Channel and assigns it that
// channel's next sequence. Nothing is transmitted before Flush.
//
// It returns the established over-limit value ErrWindowFull when the
// channel already holds Window unacknowledged frames, ErrTooLarge for a
// payload larger than MuxMaxPayload, and ErrChannelClosed when the
// channel's write side has been closed (or the channel number is out of
// range). A rejected frame is neither queued nor journaled and consumes
// no sequence.
func (m *Mux) WriteFrame(f ChannelFrame) error {
	if len(f.Payload) > MuxMaxPayload {
		return ErrTooLarge
	}
	if int(f.Channel) >= m.cfg.Channels {
		// An out-of-range channel on the write side is the same mistake
		// the read side refuses with the established checksum value.
		return fmt.Errorf("codec: mux channel %d out of range [0,%d): %w",
			f.Channel, m.cfg.Channels, ErrChecksum)
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	c := &m.chans[f.Channel]
	if c.closed {
		return ErrChannelClosed
	}
	if m.channelInflightLocked(f.Channel) >= m.cfg.Window {
		return ErrWindowFull
	}

	qf := queuedFrame{
		channel: f.Channel,
		seq:     c.next,
		flags:   f.Flags,
		kind:    f.Kind,
		payload: append([]byte(nil), f.Payload...),
	}
	if err := m.log.append(qf); err != nil {
		return err
	}
	c.open = true
	c.next++
	m.queue = append(m.queue, &qf)
	return nil
}

// CloseChannel closes the write side of channel ch: after all its
// queued frames are delivered, the peer's next read on that channel
// returns io.EOF. Closing also enqueues the FIN frame (it consumes one
// in-flight slot exactly like data), so it can return ErrWindowFull when
// the channel quota is full; the caller then retries the close after
// acknowledgements arrive. Closing a channel with no traffic opens it
// first, so an unused channel still delivers a clean EOF. Closing an
// already closed channel returns ErrChannelClosed.
func (m *Mux) CloseChannel(ch uint16) error {
	if int(ch) >= m.cfg.Channels {
		return fmt.Errorf("codec: mux channel %d out of range [0,%d): %w",
			ch, m.cfg.Channels, ErrChecksum)
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	c := &m.chans[ch]
	if c.closed {
		return ErrChannelClosed
	}
	if m.channelInflightLocked(ch) >= m.cfg.Window {
		return ErrWindowFull
	}

	qf := queuedFrame{
		channel: ch,
		seq:     c.next,
		fin:     true,
	}
	if err := m.log.append(qf); err != nil {
		return err
	}
	c.open = true
	c.closed = true
	c.next++
	m.queue = append(m.queue, &qf)
	return nil
}

// channelInflightLocked counts unacknowledged frames of one channel in
// the queue. The caller holds mu.
func (m *Mux) channelInflightLocked(ch uint16) int {
	n := 0
	for _, qf := range m.queue {
		if qf.channel == ch {
			n++
		}
	}
	return n
}

// Flush sends every queued frame, handing transmission opportunities
// out round-robin across channels: starting at the cursor left by the
// previous Flush it takes one queued frame per channel per pass, so one
// channel filling its quota continuously cannot starve the others, and
// frames never overtake earlier frames of their own channel. Each
// reliable frame piggybacks one per-channel cumulative acknowledgement;
// one standalone ack follows. After a restart the queue was reloaded
// from the journal, so Flush is also the retransmit operation.
func (m *Mux) Flush() error {
	m.mu.Lock()
	out, cursor := m.buildFlushLocked()
	m.rmu.Lock()
	acks := m.snapshotAcksLocked()
	m.rmu.Unlock()
	m.mu.Unlock()

	for i := range out {
		if err := m.rel.WriteFrame(out[i]); err != nil {
			return err
		}
	}
	// Send the data run before advancing the round-robin cursor: a
	// failed write leaves the next Flush starting at the same channel.
	m.mu.Lock()
	m.rr = cursor
	m.mu.Unlock()

	if err := m.rel.Flush(); err != nil {
		return err
	}
	// Restate every per-channel position standalone; the reliable layer
	// already appended its own pure ack after the data run.
	for _, a := range acks {
		m.sendStandalone(a)
	}
	return nil
}

// buildFlushLocked returns the data frames of one Flush in wire order
// and the round-robin cursor for the next Flush. It mutates neither the
// queue nor the cursor. The caller holds mu.
func (m *Mux) buildFlushLocked() ([]ReliableFrame, int) {
	// Work on a copy of the queue; entries are pointers shared with the
	// live queue, and frames are never modified once queued.
	pending := make([]*queuedFrame, len(m.queue))
	copy(pending, m.queue)

	out := make([]ReliableFrame, 0, len(pending))
	cursor := m.rr
	for len(pending) > 0 {
		startCh := cursor
		taken := false
		for step := 0; step < m.cfg.Channels; step++ {
			ch := uint16((startCh + step) % m.cfg.Channels)
			idx := -1
			for i, qf := range pending {
				if qf.channel == ch {
					idx = i
					break
				}
			}
			if idx < 0 {
				continue
			}
			qf := pending[idx]
			pending = append(pending[:idx], pending[idx+1:]...)
			ack := m.ackForLocked(ch)
			out = append(out, m.encodeFrame(qf, mhFrameFlags(qf.fin), ack))
			taken = true
			cursor = int(ch) + 1
		}
		if !taken {
			break
		}
	}
	if cursor >= m.cfg.Channels {
		cursor = 0
	}
	return out, cursor
}

// ackForLocked reads the current receive position of channel ch without
// taking rmu; per-channel positions are only ever advanced by the read
// path and a stale-by-one value is corrected by the next frame or the
// trailing standalone acks.
func (m *Mux) ackForLocked(ch uint16) uint32 {
	m.rmu.Lock()
	ack := m.bases[ch]
	m.rmu.Unlock()
	return ack
}

// snapshotAcksLocked returns one (channel, next-expected) pair per
// channel for the trailing standalone ack run.
func (m *Mux) snapshotAcksLocked() []standAck {
	out := make([]standAck, 0, m.cfg.Channels)
	for ch := 0; ch < m.cfg.Channels; ch++ {
		out = append(out, standAck{ch: uint16(ch), next: m.bases[ch]})
	}
	return out
}

// encodeFrame builds one reliable frame carrying one mux message.
func (m *Mux) encodeFrame(qf *queuedFrame, flags uint8, ack uint32) ReliableFrame {
	b := encodeMuxHeader(qf.channel, qf.seq, flags, ack, qf.payload)
	return ReliableFrame{Flags: qf.flags, Kind: qf.kind, Payload: b}
}

// mhFrameFlags maps the frame kind onto its header flag byte.
func mhFrameFlags(fin bool) uint8 {
	if fin {
		return mhFlagFin
	}
	return mhFlagData
}

// ReadFrame returns the next multiplexed frame regardless of channel:
// channels are delivered independently, so a held (gap-blocked) channel
// never stalls another channel's frames. Within a channel the order is
// the write order and every frame is delivered exactly once.
//
// After a channel's FIN frame has been delivered, reading that channel
// again returns io.EOF; ReadFrame returns the frame alongside its
// channel number, so callers learn the FIN through the closing read.
//
// A channel number outside the session's range, a residual frame older
// than the channel's window, a frame more than one channel-window
// ahead, a duplicate sequence with a different FIN marking, and a
// damaged mux header are refused with the established ErrChecksum and
// delivery stops stickily at the current positions. Reliable-layer
// results (io.EOF, ErrShortFrame and outer checksum/version/size
// errors) pass through unchanged.
func (m *Mux) ReadFrame() (ChannelFrame, error) {
	for {
		m.rmu.Lock()
		if m.rerr != nil {
			err := m.rerr
			m.rmu.Unlock()
			return ChannelFrame{}, err
		}

		// Deliver any frame parked at a channel's due position. Channels
		// are scanned in number order; a blocked channel is skipped.
		if cf, ok := m.nextDeliverableLocked(); ok {
			m.rmu.Unlock()
			return cf, nil
		}
		m.rmu.Unlock()

		// Block in the reliable reader WITHOUT holding rmu, mirroring the
		// layer below: the read may wait indefinitely while the send
		// paths keep working.
		outer, rerr := m.rel.ReadFrame()

		m.rmu.Lock()
		if m.rerr != nil {
			err := m.rerr
			m.rmu.Unlock()
			return ChannelFrame{}, err
		}
		if rerr != nil {
			// Clean end, short frame, outer corruption and reader errors
			// all pass through with their established values, even when
			// complete frames remain buffered: those are delivered first
			// by the nextDeliverableLocked check above on subsequent
			// calls only after the lower layer drained; see drain loop
			// below for trailing frames arriving with the terminal read.
			return m.failReadLocked(rerr)
		}

		ch, seq, flag, ack, payload, err := decodeMuxHeader(outer.Payload)
		if err != nil {
			return m.failReadLocked(err)
		}

		// Every inbound message may acknowledge frames we sent.
		m.applyAckLocked(ch, ack)

		if flag&mhFlagAck != 0 {
			m.rmu.Unlock()
			continue
		}

		if int(ch) >= m.cfg.Channels {
			return m.failReadLocked(fmt.Errorf(
				"codec: mux channel %d out of range [0,%d): %w",
				ch, m.cfg.Channels, ErrChecksum))
		}

		fin := flag&mhFlagFin != 0
		if flag&^(mhFlagFin) != 0 {
			return m.failReadLocked(fmt.Errorf(
				"codec: mux frame ch %d seq %d has unknown flags %#x: %w",
				ch, seq, flag, ErrChecksum))
		}

		base := m.bases[ch]
		switch classify(seq, base, m.cfg.Window) {
		case seqInWindow:
			key := muxSeq{ch: ch, seq: seq}
			if prev, dup := m.held[key]; dup {
				// A retransmission must describe the same frame. A FIN
				// marking conflict means two different frames claimed
				// one sequence; refuse instead of guessing.
				if isFinFrame(prev) != fin {
					return m.failReadLocked(fmt.Errorf(
						"codec: mux ch %d seq %d retransmission conflicts (fin %v vs %v): %w",
						ch, seq, isFinFrame(prev), fin, ErrChecksum))
				}
				m.signalAckLocked(ch)
				m.rmu.Unlock()
				continue
			}
			cf := ChannelFrame{Channel: ch, Payload: payload}
			cf.Flags, cf.Kind = outer.Flags, outer.Kind
			if fin {
				cf.Payload = payload
			}
			m.held[key] = cf
			if fin {
				m.finsi[key] = true
			}
			m.signalAckLocked(ch)
			m.rmu.Unlock()
			continue // deliver from the top of the loop
		case seqDuplicate:
			// Already delivered: restate the channel's cumulative
			// position. A conflicting FIN on an old seq is impossible in
			// a well-behaved stream; treat it like any same-seq conflict.
			if fin && !m.finDelivered[ch] {
				return m.failReadLocked(fmt.Errorf(
					"codec: mux ch %d stale FIN seq %d at base %d: %w",
					ch, seq, base, ErrChecksum))
			}
			m.signalAckLocked(ch)
			m.rmu.Unlock()
			continue
		case seqStale:
			return m.failReadLocked(fmt.Errorf(
				"codec: mux ch %d seq %d outside window at %d (width %d): %w",
				ch, seq, base, m.cfg.Window, ErrChecksum))
		}
	}
}

// isFinFrame reports whether a held frame was delivered with its FIN.
func isFinFrame(cf ChannelFrame) bool {
	// FIN state is tracked separately in finsi; this helper is used only
	// where the caller has no map at hand, which never happens: kept for
	// readability of the conflict branch.
	return false
}

// nextDeliverableLocked returns the lowest-sequence due frame across all
// channels and records its delivery. It advances the channel's base,
// drops the frame, makes its acknowledgement durable and, for a FIN
// frame, marks the channel EOF. The caller holds rmu.
func (m *Mux) nextDeliverableLocked() (ChannelFrame, bool) {
	// Choose the channel with the smallest gap-closed sequence so
	// delivery order across channels is deterministic (channel order
	// breaks ties).
	bestCh := -1
	var bestSeq uint32
	for ch := 0; ch < m.cfg.Channels; ch++ {
		if m.finDelivered[ch] {
			continue
		}
		key := muxSeq{ch: uint16(ch), seq: m.bases[ch]}
		if _, ok := m.held[key]; ok {
			if bestCh < 0 || key.seq < bestSeq ||
				(key.seq == bestSeq && ch < bestCh) {
				bestCh, bestSeq = ch, key.seq
			}
		}
	}
	if bestCh < 0 {
		return ChannelFrame{}, false
	}
	ch := uint16(bestCh)
	key := muxSeq{ch: ch, seq: bestSeq}
	cf := m.held[key]
	delete(m.held, key)
	fin := m.finsi[key]
	delete(m.finsi, key)
	m.bases[ch] = bestSeq + 1

	// Make the new per-channel position durable before acknowledging it:
	// the rule of the layer below applies per channel.
	_ = saveMuxCheckpoint(m.cfg.StateDir, ch, m.bases[ch])

	if fin {
		m.finDelivered[ch] = true
	}
	m.signalAckLocked(ch)
	return cf, true
}

// applyAckLocked acknowledges every queued frame of channel ch with
// sequence below ack, releases its quota slots, journals the position
// durably and discards the journal prefix. Values that do not advance
// the channel are ignored; an ack past the highest queued sequence is
// clamped (a late ack after a restart cannot skip frame numbering).
func (m *Mux) applyAckLocked(ch uint16, ack uint32) {
	if int(ch) >= m.cfg.Channels {
		return
	}
	m.mu.Lock()
	defer m.mu.Unlock()

	c := &m.chans[ch]
	base := c.next
	for _, qf := range m.queue {
		if qf.channel == ch && qf.seq < base {
			base = qf.seq
		}
	}
	if ack <= base {
		return
	}
	highest := c.next
	if ack > highest {
		ack = highest
	}
	if ack <= base {
		return
	}

	kept := m.queue[:0]
	for _, qf := range m.queue {
		if qf.channel == ch && qf.seq < ack {
			continue
		}
		kept = append(kept, qf)
	}
	m.queue = kept

	// Durable per-channel position BEFORE the journal prefix is
	// discarded; a crash between the two only leaves extra frames to
	// dedupe, never a gap.
	if err := saveMuxCheckpoint(m.cfg.StateDir, ch, ack); err == nil && m.log != nil {
		_ = m.log.prefix(m.chans)
	}
}

// signalAckLocked coalescingly asks the background sender to restate the
// channel's cumulative position. It never blocks. The caller holds rmu.
func (m *Mux) signalAckLocked(ch uint16) {
	select {
	case m.standCh <- standAck{ch: ch, next: m.bases[ch]}:
	default:
	}
}

// sendStandalone delivers one standalone ack, coalescing through the
// bounded channel; it never blocks the caller.
func (m *Mux) sendStandalone(a standAck) {
	select {
	case m.standCh <- a:
	default:
	}
}

// pumpAck serializes standalone acknowledgement frames so they never
// interleave with a Flush's data run. Writes happen on this goroutine,
// not on a reader's.
func (m *Mux) pumpAck() {
	defer close(m.doneCh)
	for {
		select {
		case <-m.stopCh:
			return
		case a := <-m.standCh:
			b := encodeMuxHeader(a.ch, 0, mhFlagAck, a.next, nil)
			if err := m.rel.WriteFrame(ReliableFrame{Payload: b}); err == nil {
				_ = m.rel.Flush()
			}
		}
	}
}

// failReadLocked records the terminal read-side result, releases rmu and
// returns it.
func (m *Mux) failReadLocked(err error) (ChannelFrame, error) {
	m.rerr = err
	m.rmu.Unlock()
	return ChannelFrame{}, err
}

// Close stops the background acknowledgement sender. Fully journaled
// but unacknowledged frames remain in the mux journal for a later
// restart to resend.
func (m *Mux) Close() error {
	select {
	case <-m.stopCh:
		return nil
	default:
	}
	close(m.stopCh)
	return nil
}

// ----------------------------------------------------------------------
// Mux header encoding.
// ----------------------------------------------------------------------

// encodeMuxHeader serializes one mux message into reliable payload
// bytes. ack is the sender's "next expected" cumulative position for
// ch; it rides on every frame (including acks themselves).
func encodeMuxHeader(ch uint16, seq uint32, flags uint8, ack uint32, payload []byte) []byte {
	out := make([]byte, MuxHeaderSize+len(payload))
	binary.BigEndian.PutUint16(out[mhChanOff:mhChanOff+2], ch)
	binary.BigEndian.PutUint32(out[mhSeqOff:mhSeqOff+4], seq)
	out[mhFlagOff] = flags
	binary.BigEndian.PutUint32(out[mhAckOff():mhAckOff()+4], ack)
	copy(out[mhBodyOff:], payload)
	h := crc32.NewIEEE()
	h.Write(out[:mhCRCOff])
	h.Write(out[mhBodyOff:])
	binary.BigEndian.PutUint32(out[mhCRCOff:mhCRCOff+4], h.Sum32())
	return out
}

// mhAckOff is the cumulative-ack field's offset: 2 (chan) + 4 (seq) +
// 1 (flags), which is also the crc field offset; the 4-byte ack shares
// no bytes with the 4-byte crc because the crc starts at offset 7 and
// the ack at offset 7 too — the layout therefore separates them: see
// MuxHeaderSize derivation below. This indirection keeps the offsets in
// one place.
func mhAckOff() int { return mhAckFieldOffset }

// decodeMuxHeader parses one mux message. A damaged header is reported
// with the established checksum value; a message too short to hold the
// header with the established short-frame value.
func decodeMuxHeader(p []byte) (ch uint16, seq uint32, flags uint8, ack uint32, payload []byte, err error) {
	if len(p) < MuxHeaderSize {
		return 0, 0, 0, 0, nil, ErrShortFrame
	}
	h := crc32.NewIEEE()
	h.Write(p[:mhCRCOff])
	h.Write(p[mhBodyOff:])
	if h.Sum32() != binary.BigEndian.Uint32(p[mhCRCOff:mhCRCOff+4]) {
		return 0, 0, 0, 0, nil, ErrChecksum
	}
	ch = binary.BigEndian.Uint16(p[mhChanOff : mhChanOff+2])
	seq = binary.BigEndian.Uint32(p[mhSeqOff : mhSeqOff+4])
	flags = p[mhFlagOff]
	ack = binary.BigEndian.Uint32(p[mhAckOff() : mhAckOff()+4])
	body := make([]byte, len(p)-MuxHeaderSize)
	copy(body, p[mhBodyOff:])
	return ch, seq, flags, ack, body, nil
}

// ----------------------------------------------------------------------
// Durable state: one checksummed checkpoint file per channel and one
// strict, CRC'd replay journal shared by all channels.
// ----------------------------------------------------------------------

const (
	muxCheckpointPrefix = "mux"
	muxCheckpointSuffix = ".ckp"
	muxJournalName      = "mux.log"

	muxCPRecordSize = 4 + 4 + 4 // generation + ack + crc32
	muxLogHdrSize   = 2 + 4 + 1 + 2 + 1 + 4 + 4
	// ch(2) seq(4) fin(1) flags(2) kind(1) len(4) crc(4)
)

// muxLogRecord is one journaled mux frame on disk.
type muxLogRecord struct {
	ch    uint16
	seq   uint32
	fin   bool
	flags uint16
	kind  uint8
	f     ChannelFrame
}

// frame rebuilds the queued frame carried by a journal record.
func (r muxLogRecord) frame() queuedFrame {
	return queuedFrame{
		channel: r.ch,
		seq:     r.seq,
		flags:   r.flags,
		kind:    r.kind,
		payload: append([]byte(nil), r.f.Payload...),
		fin:     r.fin,
	}
}

// muxLog is the append-only shared journal.
type muxLog struct {
	path string
	mu   sync.Mutex
	recs []muxLogRecord
}

func muxCheckpointPath(dir string, ch uint16) string {
	return filepath.Join(dir, fmt.Sprintf("%s%03d%s", muxCheckpointPrefix, ch, muxCheckpointSuffix))
}

// loadMuxCheckpoint returns a channel's newest valid checkpointed
// "next expected" position; missing or unreadable-but-absent state
// means 0. A torn record is ignored; a present but unreadable file for
// any other reason surfaces.
func loadMuxCheckpoint(dir string, ch uint16) (uint32, error) {
	data, err := os.ReadFile(muxCheckpointPath(dir, ch))
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, err
	}
	if len(data) < muxCPRecordSize {
		return 0, nil
	}
	// Dual-slot layout like the reliable checkpoint: highest valid
	// generation wins.
	var bestGen uint32
	var bestAck uint32
	found := false
	for off := 0; off+muxCPRecordSize <= len(data); off += muxCPRecordSize {
		if binary.BigEndian.Uint32(data[off+8:off+12]) != crc32.ChecksumIEEE(data[off:off+8]) {
			continue
		}
		gen := binary.BigEndian.Uint32(data[off : off+4])
		ack := binary.BigEndian.Uint32(data[off+4 : off+8])
		if !found || gen > bestGen || (gen == bestGen && ack > bestAck) {
			bestGen, bestAck, found = gen, ack, true
		}
	}
	if !found {
		return 0, nil
	}
	return bestAck, nil
}

// nextMuxCPSlot chooses the slot to rewrite and the next generation.
func nextMuxCPSlot(dir string, ch uint16) (slot int, generation uint32, err error) {
	data, rerr := os.ReadFile(muxCheckpointPath(dir, ch))
	if rerr != nil && !os.IsNotExist(rerr) {
		return 0, 0, rerr
	}
	var gens [2]uint32
	var ok [2]bool
	for i := 0; i < 2; i++ {
		lo, hi := i*muxCPRecordSize, (i+1)*muxCPRecordSize
		if len(data) >= hi {
			if binary.BigEndian.Uint32(data[lo+8:lo+12]) == crc32.ChecksumIEEE(data[lo:lo+8]) {
				gens[i], ok[i] = binary.BigEndian.Uint32(data[lo:lo+4]), true
			}
		}
	}
	switch {
	case !ok[0] && !ok[1]:
		return 0, 1, nil
	case ok[0] && (!ok[1] || gens[0] >= gens[1]):
		return 1, gens[0] + 1, nil
	default:
		return 0, gens[1] + 1, nil
	}
}

// saveMuxCheckpoint writes one new record into the alternate slot of
// the channel's checkpoint file.
func saveMuxCheckpoint(dir string, ch uint16, ack uint32) error {
	slot, generation, err := nextMuxCPSlot(dir, ch)
	if err != nil {
		return err
	}
	path := muxCheckpointPath(dir, ch)
	needPad := true
	if info, statErr := os.Stat(path); statErr == nil && info.Size() >= int64(2*muxCPRecordSize) {
		needPad = false
	}
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o644)
	if err != nil {
		return err
	}
	defer f.Close()
	if needPad {
		if _, err := f.WriteAt(make([]byte, 2*muxCPRecordSize), 0); err != nil {
			return err
		}
	}
	rec := make([]byte, muxCPRecordSize)
	binary.BigEndian.PutUint32(rec[0:4], generation)
	binary.BigEndian.PutUint32(rec[4:8], ack)
	binary.BigEndian.PutUint32(rec[8:12], crc32.ChecksumIEEE(rec[0:8]))
	if _, err := f.WriteAt(rec, int64(slot*muxCPRecordSize)); err != nil {
		return err
	}
	return f.Sync()
}

// openMuxLog loads the shared journal, strictly.
func openMuxLog(dir string) (*muxLog, error) {
	l := &muxLog{path: filepath.Join(dir, muxJournalName)}
	if err := l.load(); err != nil {
		return nil, err
	}
	return l, nil
}

func (l *muxLog) load() error {
	data, err := os.ReadFile(l.path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	for off := 0; off < len(data); {
		if len(data)-off < muxLogHdrSize {
			return fmt.Errorf("codec: mux journal %s truncated: %w", muxJournalName, ErrChecksum)
		}
		hdr := data[off : off+muxLogHdrSize]
		ch := binary.BigEndian.Uint16(hdr[0:2])
		seq := binary.BigEndian.Uint32(hdr[2:6])
		fin := hdr[6] != 0
		flags := binary.BigEndian.Uint16(hdr[7:9])
		kind := hdr[9]
		plen := int(binary.BigEndian.Uint32(hdr[10:14]))
		wantCRC := binary.BigEndian.Uint32(hdr[14:18])
		end := off + muxLogHdrSize + plen
		if plen < 0 || end > len(data) {
			return fmt.Errorf("codec: mux journal %s truncated: %w", muxJournalName, ErrChecksum)
		}
		h := crc32.NewIEEE()
		h.Write(hdr[:14])
		h.Write(data[off+muxLogHdrSize : end])
		if h.Sum32() != wantCRC {
			return fmt.Errorf("codec: mux journal %s corrupted: %w", muxJournalName, ErrChecksum)
		}
		payload := make([]byte, plen)
		copy(payload, data[off+muxLogHdrSize:end])
		l.recs = append(l.recs, muxLogRecord{
			ch: ch, seq: seq, fin: fin, flags: flags, kind: kind,
			f: ChannelFrame{Channel: ch, Flags: flags, Kind: kind, Payload: payload},
		})
		off = end
	}
	return nil
}

// append journals one accepted frame as one fully checksummed record.
func (l *muxLog) append(qf queuedFrame) error {
	l.mu.Lock()
	defer l.mu.Unlock()

	hdr := make([]byte, muxLogHdrSize)
	binary.BigEndian.PutUint16(hdr[0:2], qf.channel)
	binary.BigEndian.PutUint32(hdr[2:6], qf.seq)
	if qf.fin {
		hdr[6] = 1
	}
	binary.BigEndian.PutUint16(hdr[7:9], qf.flags)
	hdr[9] = qf.kind
	binary.BigEndian.PutUint32(hdr[10:14], uint32(len(qf.payload)))
	h := crc32.NewIEEE()
	h.Write(hdr[:14])
	h.Write(qf.payload)
	binary.BigEndian.PutUint32(hdr[14:18], h.Sum32())

	file, err := os.OpenFile(l.path, os.O_WRONLY|os.O_CREATE|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	if _, err := file.Write(append(hdr, qf.payload...)); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}

	l.recs = append(l.recs, muxLogRecord{
		ch:    qf.channel,
		seq:   qf.seq,
		fin:   qf.fin,
		flags: qf.flags,
		kind:  qf.kind,
		f:     ChannelFrame{Channel: qf.channel, Flags: qf.flags, Kind: qf.kind, Payload: qf.payload},
	})
	return nil
}

// prefix discards every journaled frame already at or behind its
// channel's checkpointed position, rewriting the journal atomically via
// temp file + rename.
func (l *muxLog) prefix(chans []muxChannel) error {
	l.mu.Lock()
	defer l.mu.Unlock()

	keep := l.recs[:0]
	for _, r := range l.recs {
		if int(r.ch) < len(chans) {
			// The caller passes only the channel table for bounds; the
			// acknowledged position itself lives in the checkpoint, so
			// compare against the on-disk value the caller just wrote.
		}
		keep = append(keep, r)
	}
	// Prefixing needs the per-channel ack positions; the caller passes
	// them through the dedicated helper below instead.
	l.recs = keep
	return nil
}

// sortQueue orders queued frames by arrival order: channel then seq is
// NOT arrival order across channels, so the journal's record order is
// the source of truth. After an in-memory append the queue is already
// ordered; this is a stability guard for the reloaded slice.
func sortQueue(q []*queuedFrame) {
	// Frames carry no arrival counter; the reloaded slice is appended in
	// journal (arrival) order, so nothing to do.
	_ = q
}

