// sameChannelFrame compares two parked copies of one sequence.
func sameChannelFrame(a, b ChannelFrame) bool {
	return a.Flags == b.Flags && a.Kind == b.Kind && bytesEqual(a.Payload, b.Payload)
}

func bytesEqual(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

