	if _, err := rcv.ReadFrame(); !errors.Is(err, ErrChecksum) {
		t.Fatalf("bitflip err = %v, want ErrChecksum", err)
	}
	if _, err := rcv.ReadFrame(); !errors.Is(err, ErrChecksum) {
		t.Fatalf("sticky err = %v, want ErrChecksum", err)
	}
}

func TestMuxBufferedFramesDeliveredBeforeEOF(t *testing.T) {
	cfg := muxCfg(1, 8)
