func TestMuxChannelsDeliverIndependently(t *testing.T) {
	cfg := muxCfg(t, 3, 8)
	// Only ch2 has frames; a silent ch0/ch1 must not block it.
	wire := envWire(t,
		envelope{typ: envTypeData, kind: outerKind, payload: encodeMuxHeader(2, 0, 0, 0, []byte("x"))},
		envelope{typ: envTypeData, kind: outerKind, payload: encodeMuxHeader(2, 1, 0, 0, []byte("y"))},
	)
	f := newFeed()
	rcv := newMuxReceiver(t, f, cfg)
	f.replace(wire)
	got := drainMux(t, rcv, 2)
	if got[0].Channel != 2 || string(got[0].Payload) != "x" ||
		got[1].Channel != 2 || string(got[1].Payload) != "y" {
		t.Fatalf("got %+v", got)
	}
}

func TestMuxPerChannelOutOfOrderParked(t *testing.T) {
	cfg := muxCfg(t, 2, 8)
	// ch0 arrives 1,0; ch2-style interleaving does not disturb it.
	wire := envWire(t,
		envelope{typ: envTypeData, kind: outerKind, payload: encodeMuxHeader(0, 1, 0, 0, []byte("one"))},
		envelope{typ: envTypeData, kind: outerKind, payload: encodeMuxHeader(1, 0, 0, 0, []byte("B-zero"))},
		envelope{typ: envTypeData, kind: outerKind, payload: encodeMuxHeader(0, 0, 0, 0, []byte("zero"))},
	)
	f := newFeed()
	rcv := newMuxReceiver(t, f, cfg)
	f.replace(wire)
	got := drainMux(t, rcv, 3)
	// ch1's frame goes first (nothing blocks it), then ch0 in order.
	want := []string{"1:B-zero", "0:zero", "0:one"}
	for i, w := range want {
		g := fmt.Sprintf("%d:%s", got[i].Channel, got[i].Payload)
		if g != w {
			t.Fatalf("frame %d = %s, want %s", i, g, w)
		}
	}
}

func TestMuxDuplicatesDeliveredOnce(t *testing.T) {
	cfg := muxCfg(t, 1, 8)
	one := envelope{typ: envTypeData, kind: outerKind, payload: encodeMuxHeader(0, 0, 0, 0, []byte("a"))}
	two := envelope{typ: envTypeData, kind: outerKind, payload: encodeMuxHeader(0, 1, 0, 0, []byte("bb"))}
	wire := envWire(t, one, two, one, two) // whole run resent
	f := newFeed()
	rcv := newMuxReceiver(t, f, cfg)
	f.replace(wire)
	got := drainMux(t, rcv, 2)
	if string(got[0].Payload) != "a" || string(got[1].Payload) != "bb" {
		t.Fatalf("got %+v", got)
	}
	f.closeFeed()
	if _, err := rcv.ReadFrame(); !errors.Is(err, io.EOF) {
		t.Fatalf("err = %v, want io.EOF with no duplicate delivery", err)
	}
}

func TestMuxRejectBeyondWindowAndAncient(t *testing.T) {
	const W = 4
	cfg := muxCfg(t, 1, W)

	// Exactly one window width ahead: refused.
	wire := envWire(t,
		envelope{typ: envTypeData, kind: outerKind, payload: encodeMuxHeader(0, W, 0, 0, []byte("far"))},
	)
	f := newFeed()
	rcv := newMuxReceiver(t, f, cfg)
	f.replace(wire)
	if _, err := rcv.ReadFrame(); !errors.Is(err, ErrChecksum) {
		t.Fatalf("too-far err = %v, want ErrChecksum", err)
	}

	// Ancient residual older than one window width after progress.
	f2 := newFeed()
	rcv2 := newMuxReceiver(t, f2, cfg)
	rcv2.bases[0] = 2 * W
	old := envWire(t, envelope{typ: envTypeData, kind: outerKind, payload: encodeMuxHeader(0, 0, 0, 0, []byte("old"))})
	f2.replace(old)
	if _, err := rcv2.ReadFrame(); !errors.Is(err, ErrChecksum) {
		t.Fatalf("ancient err = %v, want ErrChecksum", err)
	}

