	// Ack two ch0 frames at the mux layer: two quota slots free,
	// numbering continues at 3. (The send-only reliable layer is never
	// acked, so its next Flush also re-sends the still-windowed ch0:2;
	// the fresh reliable sequences are what parseMuxWire selects.)
	snd.applyAck(0, 2)
	if err := snd.WriteFrame(ChannelFrame{Channel: 0, Kind: 99, Payload: []byte("after")}); err != nil {
		t.Fatalf("write after ack: %v", err)
	}
