	if err := snd.Flush(); err != nil {
		t.Fatal(err)
	}
	var ch0 []uint32
	for _, w := range parseMuxWire(t, wire.Bytes(), 4) {
		if w.ch == 0 {
			ch0 = append(ch0, w.seq)
